package net.officefloor.hq.app.project;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.tag.Tag;

/** A project done for a client. */
@Entity
@Table(name = "project")
public class Project {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String code;

    private String description;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "client_id", nullable = false)
    private Client client;

    private boolean archived;

    @Enumerated(EnumType.STRING)
    private ProjectStatus status = ProjectStatus.ACTIVE;

    private BigDecimal budget;

    @ManyToMany
    @JoinTable(name = "project_tag", joinColumns = @JoinColumn(name = "project_id"),
            inverseJoinColumns = @JoinColumn(name = "tag_id"))
    private Set<Tag> tags = new HashSet<>();

    protected Project() {
    }

    public Project(String name, String code, Client client) {
        this.name = name;
        this.code = code;
        this.client = client;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    /** The job's short reference code, unique across jobs; null for jobs added before codes existed. */
    public String getCode() {
        return code;
    }

    /** A short description of the work, or null when none was given. */
    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public Client getClient() {
        return client;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    public ProjectStatus getStatus() {
        return status;
    }

    public void setStatus(ProjectStatus status) {
        this.status = status;
    }

    /** The amount this project is to be invoiced within, or null when no budget is set. */
    public BigDecimal getBudget() {
        return budget;
    }

    public void setBudget(BigDecimal budget) {
        this.budget = budget;
    }

    /** The tags labelling this project; add or remove to tag or untag it. */
    public Set<Tag> getTags() {
        return tags;
    }
}
package net.officefloor.hq.app.project;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/projects")
public class ProjectController {

    private final ProjectService service;

    public ProjectController(ProjectService service) {
        this.service = service;
    }

    @GetMapping
    public List<ProjectResponse> list(@RequestParam(defaultValue = "false") boolean includeArchived,
            @RequestParam(required = false) Long tagId, @RequestParam(required = false) ProjectStatus status) {
        return service.list(includeArchived, tagId, status);
    }

    @GetMapping("/{id}")
    public ProjectResponse get(@PathVariable Long id) {
        return service.get(id);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ProjectResponse create(@Valid @RequestBody ProjectRequest request) {
        return service.create(request);
    }

    @PutMapping("/{id}/status")
    public ProjectResponse changeStatus(@PathVariable Long id, @Valid @RequestBody ProjectStatusRequest request) {
        return service.changeStatus(id, request.status());
    }

    @GetMapping("/{id}/budget")
    public ProjectBudgetResponse budget(@PathVariable Long id) {
        return service.budget(id);
    }

    @PutMapping("/{id}/budget")
    public ProjectBudgetResponse setBudget(@PathVariable Long id, @Valid @RequestBody ProjectBudgetRequest request) {
        return service.setBudget(id, request.budget());
    }

    @PostMapping("/{id}/archive")
    public ProjectResponse archive(@PathVariable Long id) {
        return service.archive(id);
    }

    @PostMapping("/{id}/restore")
    public ProjectResponse restore(@PathVariable Long id) {
        return service.restore(id);
    }
}
