package net.officefloor.hq.app.project;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Payload to create a project for a client; without a status the project starts active. The code is
 * a short reference of letters, digits and dashes, unique across projects. The description is an
 * optional short summary of the work.
 */
public record ProjectRequest(
        @NotBlank @Size(max = 255) String name,
        @NotBlank @Pattern(regexp = ProjectRequest.CODE_PATTERN) String code,
        @NotNull Long clientId,
        ProjectStatus status,
        @Size(max = ProjectRequest.DESCRIPTION_MAX) String description) {

    /** The longest description a job may carry. */
    public static final int DESCRIPTION_MAX = 500;

    /** Up to 20 letters, digits or dashes, ignoring surrounding whitespace. */
    public static final String CODE_PATTERN = "^\\s*[A-Za-z0-9-]{1,20}\\s*$";
}
package net.officefloor.hq.app.project;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import java.math.BigDecimal;

/** Payload to set a project's budget; without a budget the project's budget is cleared. */
public record ProjectBudgetRequest(@DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal budget) {
}
import { CurrencyPipe } from '@angular/common';
import { Component, inject, input, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { ProjectService } from './project.service';
import { CurrencyCode } from '../clients/client.service';

// A project's budget: what it is, how much has been invoiced against it (sent invoices, paid or not),
// and what is left. Set or change the budget, or clear it by leaving the amount blank.
@Component({
  selector: 'app-project-budget',
  imports: [ReactiveFormsModule, CurrencyPipe],
  template: `
    <section aria-labelledby="project-budget-heading" data-testid="project-budget-section">
      <h2 id="project-budget-heading">Budget</h2>

      @if (budget.error()) {
        <p role="alert" data-testid="project-budget-error">Could not load the budget.</p>
      } @else if (budget.hasValue()) {
        @let b = budget.value();
        <dl>
          <dt>Budget</dt>
          <dd data-testid="project-budget">
            @if (b.budget === null) {
              No budget set
            } @else {
              {{ b.budget | currency: currency() : 'symbol' : '1.2-2' : 'en-US' }}
            }
          </dd>
          <dt>Invoiced</dt>
          <dd data-testid="project-invoiced">{{ b.invoiced | currency: currency() : 'symbol' : '1.2-2' : 'en-US' }}</dd>
          <dt>Remaining</dt>
          <dd data-testid="project-remaining" [class.over]="b.remaining !== null && b.remaining < 0">
            @if (b.remaining === null) {
              —
            } @else {
              {{ b.remaining | currency: currency() : 'symbol' : '1.2-2' : 'en-US' }}
            }
          </dd>
        </dl>
        @if (b.remaining !== null && b.remaining < 0) {
          <p data-testid="project-over-budget">Invoiced over budget.</p>
        }
      }

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="project-budget-form" novalidate>
        <label for="project-budget-amount">Set budget (leave blank to clear)</label>
        <input
          id="project-budget-amount"
          type="number"
          inputmode="decimal"
          min="0"
          step="0.01"
          formControlName="budget"
          data-testid="project-budget-input"
          [attr.aria-invalid]="showError()"
          [attr.aria-describedby]="showError() ? 'project-budget-amount-error' : null"
        />
        <button type="submit" data-testid="project-budget-submit" [disabled]="saving()">Save budget</button>
        @if (showError()) {
          <p id="project-budget-amount-error" role="alert" data-testid="project-budget-input-error">
            Enter an amount of zero or more with at most two decimal places, or leave it blank.
          </p>
        }
        @if (saveError()) {
          <p role="alert" data-testid="project-budget-save-error">{{ saveError() }}</p>
        }
      </form>
    </section>
  `,
  styles: `
    dl {
      display: grid;
      grid-template-columns: max-content auto;
      gap: 0.25rem 1rem;
    }
    dd {
      margin: 0;
    }
    .over {

